"""Robust parser for UEA/UCR `.ts` classification files.

Handles both the classic layout (`label:val,val,...`) and the layout used by
the current timeseriesclassification.com aeon-toolkit zips
(`val,val,...:label`), space- or comma-separated values, and missing values
("?"). Series are returned on their RAW measurement scale (R2: no per-series
z-normalisation).
"""
from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path

import numpy as np


@dataclass
class TsData:
    X: np.ndarray            # (n_series, series_length) float, raw scale
    y: np.ndarray            # (n_series,) string class labels
    series_length: int
    header: dict = field(default_factory=dict)
    n_missing_values: int = 0
    source: str = ""


def _parse_floats(token: str) -> np.ndarray | None:
    """Parse a comma/space separated numeric token; '?' becomes NaN."""
    parts = [p for p in token.replace(",", " ").split() if p != ""]
    if not parts:
        return None
    vals = []
    for p in parts:
        if p in ("?", "NaN", "nan"):
            vals.append(np.nan)
            continue
        try:
            vals.append(float(p))
        except ValueError:
            return None
    return np.asarray(vals, dtype=float)


def _looks_like_values(token: str) -> bool:
    return _parse_floats(token) is not None


def read_ts(path: str | Path) -> TsData:
    path = Path(path)
    header: dict = {}
    rows: list[np.ndarray] = []
    labels: list[str] = []
    n_missing = 0

    with open(path, encoding="utf-8", errors="replace") as fh:
        lines = fh.readlines()

    in_data = False
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        if line.startswith("#"):
            continue  # comment
        if line.startswith("@"):
            in_data = line.strip().lower() == "@data"
            if not in_data:
                tokens = line[1:].split()
                if tokens:
                    header[tokens[0].lower()] = tokens[1] if len(tokens) > 1 else ""
            continue
        if not in_data:
            continue

        # --- split a data line into (values, label) ---
        if ":" in line:
            left, right = line.split(":", 1)
            if _looks_like_values(left) and not _looks_like_values(right):
                vals, label = left, right.strip()
            elif _looks_like_values(right) and not _looks_like_values(left):
                vals, label = right, left.strip()
            else:
                # Ambiguous (e.g. numeric-looking label with colon): prefer
                # "values:label" (current archive layout), fall back to classic.
                if _looks_like_values(left):
                    vals, label = left, right.strip()
                else:
                    vals, label = right, left.strip()
        else:
            # No colon: label may be the first or last whitespace token
            tokens = line.split()
            if _looks_like_values(" ".join(tokens[:-1])):
                vals, label = " ".join(tokens[:-1]), tokens[-1]
            else:
                vals, label = " ".join(tokens[1:]), tokens[0]

        arr = _parse_floats(vals)
        if arr is None or arr.size == 0:
            raise ValueError(f"Could not parse series values on line: {line[:80]!r}")
        rows.append(arr)
        labels.append(label)
        n_missing += int(np.isnan(arr).sum())

    if not rows:
        raise ValueError(f"No data rows parsed from {path}")

    lengths = {arr.size for arr in rows}
    if len(lengths) > 1:
        # Ragged: keep as object array only if truly unavoidable
        max_len = max(lengths)
        X = np.full((len(rows), max_len), np.nan)
        for i, arr in enumerate(rows):
            X[i, : arr.size] = arr
    else:
        X = np.vstack(rows)

    y = np.asarray(labels, dtype=object)
    return TsData(
        X=X,
        y=y,
        series_length=int(X.shape[1]),
        header=header,
        n_missing_values=n_missing,
        source=str(path),
    )


def load_train_test(data_dir: str | Path, name: str) -> tuple[TsData, TsData]:
    train = read_ts(Path(data_dir) / f"{name}_TRAIN.ts")
    test = read_ts(Path(data_dir) / f"{name}_TEST.ts")
    return train, test

